,p_title=>unistr('Como a ocupa\00E7\00E3o \00E9 calculada')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>20
,p_plug_grid_column_span=>12
,p_plug_display_column=>1
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px;padding:8px;">',
'  <div style="border-left:4px solid #0F766E;padding:8px 14px;">',
unistr('    <strong style="color:#0F766E;">Taxa de ocupa\00E7\00E3o</strong><br>'),
'    paciente-dia &divide; leito-dia<br>',
'    <span style="color:#6B7280;font-size:.9rem;">',
unistr('      Defini\00E7\00E3o padr\00E3o do Minist\00E9rio da Sa\00FAde'),
'    </span>',
'  </div>',
'  <div style="border-left:4px solid #854F0B;padding:8px 14px;">',
unistr('       <strong style="color:#854F0B;">Faixa saud\00E1vel</strong><br>'),
unistr('    75% a 85% (refer\00EAncia ANS)<br>'),
'    <span style="color:#6B7280;font-size:.9rem;">',
unistr('      Acima disso aumentam eventos adversos e infec\00E7\00E3o hospitalar.'),
unistr('      O painel sinaliza aten\00E7\00E3o a partir de 70% \2014 crit\00E9rio mais conservador.'),
'    </span>',
'  </div>',
'  <div style="border-left:4px solid #5F5E5A;padding:8px 14px;">',
'    <strong style="color:#5F5E5A;">Cobertura</strong><br>',
unistr('    17 compet\00EAncias, de 01/2025 a 05/2026<br>'),
'    <span style="color:#6B7280;font-size:.9rem;">',
unistr('      Fontes: CNES (leitos) e SIH/TabNet (perman\00EAncia)'),
'    </span>',
'  </div>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260810234719Z')
,p_updated_on=>wwv_flow_imp.dz('20260827003204Z')
