,p_updated_by=>'MARCO'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9955142233953441)
,p_plug_name=>'Abertura'
,p_static_id=>'abertura'
,p_title=>'Abertura'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4501440665235496320
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div style="padding:8px 8px 24px;">',
'  <p style="margin:0 0 16px;font-size:1.1rem;color:#4B5563;">',
unistr('    Painel Inteligente de Ocupa\00E7\00E3o Hospitalar \2014 S\00E3o Paulo Capital'),
'  </p>',
'  <p style="max-width:820px;margin:0;color:#4B5563;line-height:1.6;">',
'    O CNES sabe quantos leitos existem. O SIH sabe quantos pacientes os ocuparam',
unistr('    e por quantos dias. Nenhum sistema p\00FAblico cruza os dois \2014 e sem esse'),
unistr('    cruzamento, gestores decidem aloca\00E7\00E3o de recursos sem saber quais hospitais'),
unistr('    operam no limite. Este painel calcula a taxa de ocupa\00E7\00E3o real dos hospitais'),
'    SUS da capital paulista a partir de dados abertos do DATASUS.',
'  </p>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260810234448Z')
,p_updated_on=>wwv_flow_imp.dz('20260811000041Z')
,p_created_by=>'MARCO'
,p_updated_by=>'MARCO'
);
