,p_plug_query_num_rows=>15
,p_region_image=>'#APP_FILES#icons/app-icon-512.png'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML',
  'show_line_breaks', 'Y')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9955567612953445)
,p_plug_name=>unistr('Limita\00E7\00F5es')
,p_static_id=>unistr('limita\00E7\00F5es')
,p_title=>unistr('O que este painel n\00E3o mostra')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>40
,p_plug_grid_column_span=>12
,p_plug_display_column=>1
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul style="color:#4B5563;line-height:1.8;max-width:900px;padding-left:20px;">',
unistr('  <li>A taxa \00E9 <strong>mensal</strong> \2014 n\00E3o captura picos di\00E1rios. Monitoramento'),
unistr('      em tempo real \00E9 atribui\00E7\00E3o da regula\00E7\00E3o estadual (CROSS/SIRESP).</li>'),
unistr('  <li>Leitos do CNES s\00E3o <strong>autodeclarados</strong>. Ocupa\00E7\00E3o acima de 100%'),
unistr('      indica cadastro desatualizado, n\00E3o erro de c\00E1lculo.</li>'),
unistr('  <li>Hospitais com <strong>menos de 300 interna\00E7\00F5es</strong> em 17 meses ficam'),
unistr('      fora do ranking e das m\00E9dias da rede \2014 s\00E3o unidades de atua\00E7\00E3o intermitente'),
'      no SUS, onde percentuais viram artefato de amostra pequena.</li>',
unistr('  <li>A ocupa\00E7\00E3o m\00E9dia \00E9 <strong>m\00E9dia simples entre hospitais</strong>, n\00E3o taxa'),
'      agregada da rede.</li>',
unistr('  <li>O total de <strong>leitos cadastrados</strong> inclui os hospitais de atua\00E7\00E3o'),
unistr('      residual. A tela de Vis\00E3o Geral mostra apenas os leitos da rede ativa \2014'),
unistr('      diferen\00E7a de 44 leitos.</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260810235132Z')
,p_updated_on=>wwv_flow_imp.dz('20260818002727Z')
,p_created_by=>'MARCO'
,p_updated_by=>'MARCO'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9955348381953443)
,p_plug_name=>unistr('N\00FAmeros da rede')
,p_static_id=>unistr('n\00FAmeros-da-rede')
,p_title=>'A rede hoje'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>30
,p_plug_grid_column_span=>12
,p_plug_display_column=>1
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH ult AS (',
'  SELECT MAX(competencia) AS competencia FROM gld_ocupacao_mensal',
'),',
'base AS (',
'  SELECT o.co_cnes,',
'         o.semaforo,',
'         MAX(o.taxa_ocupacao) AS taxa_ocupacao,',
'         MAX(o.leito_dia)     AS leito_dia',
'    FROM gld_ocupacao_mensal o',
'    JOIN ult u ON u.competencia = o.competencia',
'   GROUP BY o.co_cnes, o.semaforo',
')',
'SELECT ''Hospitais monitorados'' AS titulo,',
'       TO_CHAR(COUNT(*))       AS valor,',
'       ''card-neutro''           AS css_class,',
'       1                       AS ordem',
'  FROM base',
'UNION ALL',
unistr('SELECT ''Ocupa\00E7\00E3o m\00E9dia (por hospital)'','),
'       TO_CHAR(ROUND(AVG(taxa_ocupacao), 1), ''FM990D0'') || ''%'',',
'       ''card-ok'',',
'       2',
'  FROM base',
' WHERE semaforo <> ''RESIDUAL''',
'UNION ALL',
unistr('SELECT ''Hospitais cr\00EDticos (>85%)'','),
'       TO_CHAR(COUNT(*)),',
'       ''card-critico'',',
'       3',
'  FROM base',
' WHERE semaforo = ''CRITICO''',
'UNION ALL',
'SELECT ''Leitos SUS cadastrados'',',
'       TO_CHAR(ROUND(SUM(b.leito_dia) /',
'               EXTRACT(DAY FROM LAST_DAY(TO_DATE(u.competencia, ''YYYYMM'')))),',
'               ''FM999G999''),',
'       ''card-neutro'',',
'       4',
'  FROM base b',
' CROSS JOIN ult u',
' GROUP BY u.competencia',
'ORDER BY 4'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_created_on=>wwv_flow_imp.dz('20260810234906Z')
,p_updated_on=>wwv_flow_imp.dz('20260818010332Z')
,p_created_by=>'MARCO'
,p_updated_by=>'MARCO'
);
