,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('SELECT ''Interna\00E7\00F5es no m\00EAs'' AS titulo,'),
'       TO_CHAR(internacoes, ''FM999G999'') AS valor,',
'       ''card-neutro'' AS css_class,',
'       1 AS ordem',
'  FROM gld_kpi_rede',
' WHERE competencia = :P2_COMPETENCIA',
'UNION ALL',
'SELECT ''Leitos SUS (rede ativa)'',',
'       TO_CHAR(leitos_sus, ''FM999G999''),',
'       ''card-neutro'',',
'       2',
'  FROM gld_kpi_rede',
' WHERE competencia = :P2_COMPETENCIA',
'UNION ALL',
unistr('SELECT ''Ocupa\00E7\00E3o m\00E9dia (por hospital)'','),
'       TO_CHAR(ocupacao_media_simples, ''FM990D0'') || ''%'',',
'       CASE WHEN ocupacao_media_simples > 85 THEN ''card-critico''',
'            WHEN ocupacao_media_simples >= 70 THEN ''card-atencao''',
'            ELSE ''card-ok'' END,',
'       3',
'  FROM gld_kpi_rede',
' WHERE competencia = :P2_COMPETENCIA',
'UNION ALL',
unistr('SELECT ''Ocupa\00E7\00E3o da rede (ponderada)'','),
'       TO_CHAR(ocupacao_rede, ''FM990D0'') || ''%'',',
'       CASE WHEN ocupacao_rede > 85 THEN ''card-critico''',
'            WHEN ocupacao_rede >= 70 THEN ''card-atencao''',
'            ELSE ''card-ok'' END,',
'       4',
'  FROM gld_kpi_rede',
' WHERE competencia = :P2_COMPETENCIA',
'ORDER BY 4'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P2_TIPO_UNIDADE,P2_COMPETENCIA'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_updated_on=>wwv_flow_imp.dz('20260818002506Z')
,p_updated_by=>'MARCO'
);
