wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9951195472953401)
,p_plug_name=>'KPIs Semaforo'
,p_static_id=>'kpis-semaforo'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    CASE semaforo',
unistr('        WHEN ''CRITICO''  THEN ''Cr\00EDtico (>85%)'''),
unistr('        WHEN ''ATENCAO''  THEN ''Aten\00E7\00E3o (70\201385%)'''),
'        WHEN ''OK''       THEN ''Adequado (<70%)''',
unistr('        WHEN ''RESIDUAL'' THEN ''Atua\00E7\00E3o SUS residual'''),
'    END AS titulo,',
'    COUNT(DISTINCT co_cnes) AS qtd_hospitais,',
'    ''card-'' || LOWER(semaforo) AS css_class',
'FROM gld_ocupacao_mensal',
'WHERE competencia = :P2_COMPETENCIA',
'  AND (:P2_TIPO_UNIDADE IS NULL OR ds_tipo_unidade = :P2_TIPO_UNIDADE)',
'GROUP BY semaforo',
'ORDER BY DECODE(semaforo, ''CRITICO'', 1, ''ATENCAO'', 2, ''OK'', 3, ''RESIDUAL'', 4)'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P2_TIPO_UNIDADE,P2_COMPETENCIA'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_updated_on=>wwv_flow_imp.dz('20260810230859Z')
,p_updated_by=>'MARCO'
);
