wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9952310813953413)
,p_plug_name=>'Tendencia da Rede'
,p_static_id=>'tendencia-da-rede'
,p_title=>unistr('Ocupa\00E7\00E3o m\00E9dia da rede (%)')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    competencia,',
'    TO_CHAR(TO_DATE(competencia,''YYYYMM''),''MM/YY'') AS periodo,',
'    ROUND(AVG(taxa_ocupacao), 1) AS taxa_media,',
'    ROUND(AVG(media_movel_3m), 1) AS media_movel,',
'    85 AS limite_critico',
'FROM (SELECT competencia, co_cnes,',
'             MAX(taxa_ocupacao) AS taxa_ocupacao,',
'             MAX(media_movel_3m) AS media_movel_3m',
'        FROM gld_ocupacao_mensal',
'       WHERE (:P2_TIPO_UNIDADE IS NULL OR ds_tipo_unidade = :P2_TIPO_UNIDADE)',
'         AND semaforo <> ''RESIDUAL''',
'       GROUP BY competencia, co_cnes)',
'GROUP BY competencia',
'ORDER BY competencia'))
,p_plug_source_type=>'NATIVE_JET_CHART'
,p_ajax_items_to_submit=>'P2_TIPO_UNIDADE,P2_COMPETENCIA'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_updated_on=>wwv_flow_imp.dz('20260812014441Z')
,p_updated_by=>'MARCO'
);
