wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9925118419705199)
,p_plug_name=>unistr('Vis\00E3o Geral')
,p_static_id=>unistr('vis\00E3o-geral')
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ranking_no_mes,',
'       nome_estabelecimento, ds_tipo_unidade,',
'       CASE WHEN taxa_ocupacao > 100',
unistr('            THEN TO_CHAR(taxa_ocupacao, ''FM990D0'') || '' \26A0'''),
'            ELSE TO_CHAR(taxa_ocupacao, ''FM990D0'')',
'       END AS taxa_ocupacao,',
'       LEAST(taxa_ocupacao, 100) AS taxa_largura,',
'       semaforo,',
'       CASE semaforo WHEN ''CRITICO''  THEN ''#C74634''',
'                     WHEN ''ATENCAO''  THEN ''#E8A33D''',
'                     WHEN ''RESIDUAL'' THEN ''#8A94A6''',
'                     ELSE ''#3A9B35'' END AS semaforo_cor,',
'       var_vs_mes_anterior,',
unistr('       CASE WHEN var_vs_mes_anterior > 0 THEN ''\25B2'''),
unistr('            WHEN var_vs_mes_anterior < 0 THEN ''\25BC'' ELSE ''\2013'' END AS var_icone,'),
'       CASE WHEN var_vs_mes_anterior > 0 THEN ''#C74634''',
'            WHEN var_vs_mes_anterior < 0 THEN ''#3A9B35''',
'            ELSE ''#8A94A6'' END AS var_cor,',
'       media_movel_3m, paciente_dia, leito_dia, competencia',
'  FROM gld_ocupacao_mensal',
' WHERE competencia = :P2_COMPETENCIA',
'   AND (:P2_TIPO_UNIDADE IS NULL OR ds_tipo_unidade = :P2_TIPO_UNIDADE)',
' ORDER BY ranking_no_mes NULLS LAST'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P2_TIPO_UNIDADE,P2_COMPETENCIA'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_prn_page_header=>unistr('Vis\00E3o Geral')
,p_ai_enabled=>false
,p_updated_on=>wwv_flow_imp.dz('20260824225925Z')
,p_updated_by=>'MARCO'
);
