'UNION ALL',
'SELECT ''Grupo'', cluster_nome, 1',
'  FROM gld_fatores_hospital WHERE co_cnes = :P3_HOSPITAL',
'UNION ALL',
unistr('SELECT ''Ocupa\00E7\00E3o m\00E9dia'','),
'       TO_CHAR(taxa_media, ''FM990D0'') || ''%'', 2',
'  FROM gld_fatores_hospital WHERE co_cnes = :P3_HOSPITAL',
'UNION ALL',
unistr('SELECT ''M\00E9dia do grupo'','),
'       TO_CHAR(taxa_cluster, ''FM990D0'') || ''%'', 3',
'  FROM gld_fatores_hospital WHERE co_cnes = :P3_HOSPITAL',
'UNION ALL',
unistr('SELECT ''Posi\00E7\00E3o frente ao grupo'','),
'       TO_CHAR(dif_taxa_pp, ''FMS990D0'') || '' p.p.'', 4',
'  FROM gld_fatores_hospital WHERE co_cnes = :P3_HOSPITAL',
'UNION ALL',
'SELECT ''Ranking no grupo'',',
unistr('       rank_no_cluster || ''\00BA de '' || n_cluster, 5'),
'  FROM gld_fatores_hospital WHERE co_cnes = :P3_HOSPITAL',
'UNION ALL',
unistr('SELECT ''Perman\00EAncia m\00E9dia'','),
'       TO_CHAR(perm_media, ''FM990D0'') || '' dias'', 6',
'  FROM gld_fatores_hospital WHERE co_cnes = :P3_HOSPITAL',
'UNION ALL',
'SELECT ''Leitos SUS'',',
