,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT CASE fator_dominante',
'         WHEN ''VOLUME''        THEN ''Volume''',
unistr('         WHEN ''PERMANENCIA''   THEN ''Perman\00EAncia'''),
'         WHEN ''GRAVIDADE''     THEN ''Gravidade''',
'         WHEN ''COMPLEXIDADE''  THEN ''Complexidade''',
'         WHEN ''MULTIFATORIAL'' THEN ''Multifatorial''',
unistr('         ELSE ''Sem press\00E3o'''),
'       END AS fator,',
'       COUNT(*) AS qtd',
'  FROM gld_fatores_hospital',
' WHERE taxa_media > 85',
' GROUP BY fator_dominante',
' ORDER BY qtd DESC'))
